"""Versioned native Miles adapter with explicit interrupted-transport provenance.

Original accepted policy turns remain the only token/loss targets. Missing
responses stay missing and consume conservative resource reservations. This does
not declare an interrupted collection eligible for the frozen training study.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from ndfeb_sps.miles_investigation import _number, _require, attach_terminal_reward
from ndfeb_sps.vllm_investigation import build_vllm_investigation as build_v1


def recovery_provenance(bundle):
    binding = bundle.get("unknown_usage_recovery")
    if binding is None:
        return {"interrupted_attempts": [], "reserved_unknown_prompt_tokens": 0,
                "reserved_unknown_generated_tokens": 0, "actual_unknown_usage": None}
    file = Path(binding["path"])
    raw = file.read_bytes()
    _require(hashlib.sha256(raw).hexdigest() == binding["sha256"], "Recovery receipt bytes changed")
    receipt = json.loads(raw)
    _require(receipt == binding["receipt"], "Embedded recovery differs from original receipt")
    _require(receipt.get("schema") == "ndfeb-vllm-unknown-usage-recovery-v1"
             and receipt.get("owner_verified") is True and receipt.get("reason"), "Unreviewed transport recovery")
    entries = receipt.get("entries")
    _require(isinstance(entries, list) and entries, "Empty interrupted-attempt provenance")
    seen = set()
    root = file.parent
    rows = [json.loads(line) for line in (root / "usage.jsonl").read_text().splitlines() if line]
    unknown = {row["accounting_id"]: row for row in rows if row["status"] != "known"}
    _require(len(unknown) == len(entries), "Recovery does not preserve all unresolved attempts")
    accepted = {turn["call_id"] for turn in bundle["turns"]}
    for entry in entries:
        key = entry["accounting_id"]
        _require(key not in seen and key in unknown, "Duplicate or missing unknown attempt")
        seen.add(key)
        _require(entry["call_id"] == unknown[key]["call_id"] and entry["call_id"] not in accepted,
                 "Missing response cannot become an accepted policy turn")
        _require(entry.get("usage_known") is False and entry.get("output_recovered") is False,
                 "Unknown output or usage must not be invented")
        _require(entry.get("prompt_token_reserve") == 131072 and entry.get("generated_token_reserve") == 32768,
                 "Local unknown attempt must reserve full configured context and output")
        for kind in ("request", "failure"):
            relative = Path(entry[kind + "_relative_path"])
            _require(len(relative.parts) == 2 and relative.parts[0] == "api"
                     and relative.name.startswith(kind + "_") and relative.suffix == ".json",
                     "Recovery must bind original local API receipts")
            source = root / relative
            payload = source.read_bytes()
            _require(hashlib.sha256(payload).hexdigest() == entry[kind + "_sha256"], "Interrupted receipt changed")
            original = json.loads(payload)
            _require(original["accounting_id"] == key and original["call_id"] == entry["call_id"],
                     "Interrupted identity changed")
            if kind == "request":
                _require(original["wire_request_sha256"] == entry["wire_request_sha256"], "Unknown native request changed")
    return {"recovery_receipt_sha256": binding["sha256"], "interrupted_attempts": entries,
            "reserved_unknown_prompt_tokens": sum(e["prompt_token_reserve"] for e in entries),
            "reserved_unknown_generated_tokens": sum(e["generated_token_reserve"] for e in entries),
            "actual_unknown_usage": None, "output_recovered": False,
            "sample_scope": "accepted native continuations only; missing responses have no token/loss targets"}


def build_vllm_investigation(bundle, tokenizer, *, expected_policy, allow_test_fixtures=False):
    recovery = recovery_provenance(bundle)
    samples, audit = build_v1(bundle, tokenizer, expected_policy=expected_policy,
                             allow_test_fixtures=allow_test_fixtures)
    audit["interrupted_transport_provenance"] = recovery
    audit["http_stack"] = bundle.get("http_stack")
    for sample, turn in zip(samples, bundle["turns"], strict=True):
        sample.metadata["interrupted_transport_provenance"] = recovery
        # Original V1 turns had no explicit HTTP-stack receipt. Preserve that
        # absence instead of assigning the later V2 transport to earlier tokens.
        sample.metadata["http_stack"] = turn.get("http_stack")
        sample.metadata["http_stack_metadata_available"] = "http_stack" in turn
        sample.metadata["training_admission"] = "local diagnostic only; interrupted collection and numerical deployment require separate admission"
    return samples, audit


def main(argv=None):
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--capture", type=Path, required=True)
    parser.add_argument("--policy", type=Path, required=True)
    parser.add_argument("--tokenizer", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--assessment", type=Path)
    parser.add_argument("--reward-contract", type=Path)
    args = parser.parse_args(argv)
    _require(not args.output.exists(), "Refusing to overwrite original assembly")
    _require(bool(args.assessment) == bool(args.reward_contract), "Assessment and reward contract are paired")
    from transformers import AutoTokenizer

    bundle = json.loads(args.capture.read_text())
    policy = json.loads(args.policy.read_text())
    tokenizer = AutoTokenizer.from_pretrained(args.tokenizer, local_files_only=True, trust_remote_code=False)
    samples, audit = build_vllm_investigation(bundle, tokenizer, expected_policy=policy)
    reward = None
    if args.assessment:
        assessment = json.loads(args.assessment.read_text())
        reward = assessment.get("result", assessment).get("reward")
        _require(_number(reward), "Independent assessment has no finite optimization label")
        attach_terminal_reward(samples, terminal_reward=reward,
                               reward_receipt_sha256=hashlib.sha256(args.assessment.read_bytes()).hexdigest(),
                               reward_contract_sha256=hashlib.sha256(args.reward_contract.read_bytes()).hexdigest())
        for sample in samples:
            sample.metadata["training_admission"] = "local diagnostic only; no updates authorized"
            type(sample).from_dict(sample.to_dict()).validate()
    result = {"schema": "ndfeb-vllm-native-miles-assembly-v2", "audit": audit,
              "capture_file_sha256": hashlib.sha256(args.capture.read_bytes()).hexdigest(),
              "samples": [sample.to_dict() for sample in samples], "weight_updates": 0,
              "reward_supplied": args.assessment is not None, "reward": reward,
              "assessment_path": str(args.assessment) if args.assessment else None,
              "training_admission": False, "frozen_fp8_study_eligible": False}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open("x") as stream:
        json.dump(result, stream, indent=2, allow_nan=False)
        stream.write("\n")
    print(json.dumps({"status": "assembled_no_update", "turns": len(samples), "output": str(args.output)}))


if __name__ == "__main__":
    main()
